      }
    }
  }
  .\[\&\[aria-orientation\=horizontal\]\>div\]\:rotate-90 {
    &[aria-orientation=horizontal] > div {
      rotate: 90deg;
    }
  }
  .\[\&\[data-state\=open\]\>svg\]\:rotate-180 {
    &[data-state=open] > svg {
      rotate: 180deg;
    }
  }
  .\[\[data-side\=left\]\[data-collapsible\=offcanvas\]_\&\]\:-right-2 {
    [data-side=left][data-collapsible=offcanvas] & {
      right: calc(var(--spacing) * -2);
    }
  }
  .\[\[data-side\=left\]\[data-state\=collapsed\]_\&\]\:cursor-e-resize {
    [data-side=left][data-state=collapsed] & {
      cursor: e-resize;
    }
  }
  .\[\[data-side\=right\]\[data-collapsible\=offcanvas\]_\&\]\:-left-2 {
    [data-side=right][data-collapsible=offcanvas] & {
      left: calc(var(--spacing) * -2);
    }
  }
  .\[\[data-side\=right\]\[data-state\=collapsed\]_\&\]\:cursor-w-resize {
    [data-side=right][data-state=collapsed] & {
      cursor: w-resize;
    }
  }
  .\[\[data-slot\=card-content\]_\&\]\:bg-transparent {
    [data-slot=card-content] & {
      background-color: transparent;
    }
  }
  .\[\[data-slot\=popover-content\]_\&\]\:bg-transparent {
    [data-slot=popover-content] & {
      background-color: transparent;
    }
  }
  .\[\[data-variant\=legend\]\+\&\]\:-mt-1\.5 {
    [data-variant=legend] + & {
      margin-top: calc(var(--spacing) * -1.5);
    }
  }
  .\[a\&\]\:hover\:underline {
    a& {
      &:hover {
        @media (hover: hover) {
          text-decoration-line: underline;
        }
      }
    }
  }
}
:root {
  font-family: var(--font-ui);
  color: #363330;
  background: #f2f0ed;
  font-synthesis: none;
}
* {
  box-sizing: border-box;
}
body {
  margin: 0;
}
button,
input,
select,
textarea {
  font: inherit;
}
button,
a,
input,
select,
textarea {
  -webkit-tap-highlight-color: transparent;
}
button {
  cursor: pointer;
  border: 0;
  background: none;
  color: inherit;
}
button:disabled {
  cursor: default;
  opacity: .4;
}
button:focus-visible,
a:focus-visible {
  outline: 2px solid #956e87;
  outline-offset: 2px;
}
input,
textarea,
select {
  color: inherit;
}
input:focus,
textarea:focus,
select:focus {
  outline: 2px solid #b69aa9;
  outline-offset: -1px;
}
textarea {
  resize: vertical;
}
a {
  color: inherit;
  text-decoration: none;
}
button svg,
a svg {
  flex-shrink: 0;
}
svg {
  vertical-align: middle;
}
::selection {
  background: #dec9d7;
}
button,
input,
textarea,
select {
  border-radius: 4px;
}
.studio {
  --bg: #f8f7f4;
  --surface: #fff;
  --side: #f2f0ec;
  --line: #e1ded8;
  --text: #37332f;
  --muted: #928b83;
  --accent: #76536a;
  --accent-soft: #e9dfe6;
  --paper: #fff;
  --editor: #eae8e3;
  display: flex;
  flex-direction: column;
  height: 100dvh;
  min-height: 400px;
  color: var(--text);
  background: var(--bg);
  font-size: 13px;
  overflow: hidden;
}
.studio.dark {
  --bg: #29272b;
  --surface: #302d32;
  --side: #262429;
  --line: #423d44;
  --text: #ded8df;
  --muted: #a197a4;
  --accent: #c79ab8;
  --accent-soft: #4b3b49;
  --paper: #322f34;
  --editor: #232126;
}
.icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 29px;
  flex-shrink: 0;
  border-radius: 5px;
  color: #817971;
}
.dark .icon-button {
  color: var(--muted);
}
.icon-button:hover {
  background: #00000007;
  color: var(--text);
}
.icon-button.is-active {
  color: var(--accent);
  background: var(--accent-soft);
}
.app-header {
  flex-shrink: 0;
  position: relative;
  z-index: 20;
}
.menubar {
  height: 37px;
  display: flex;
  align-items: center;
  padding: 0 15px;
  border-bottom: 1px solid var(--line);
  gap: 22px;
  background: var(--bg);
}
.app-wordmark {
  display: flex;
  align-items: center;
  gap: 9px;
  font-weight: 600;
  color: var(--accent);
  font-size: 13px;
  white-space: nowrap;
  padding: 0;
}
.menubar nav {
  display: flex;
  height: 100%;
  gap: 1px;
  align-items: center;
}
.menu-host {
  position: relative;
}
.menubar nav .menu-host > button {
  font-size: 12px;
  padding: 6px 9px;
  border-radius: 4px;
}
.menu-host > button:hover,
.menu-host > button.open {
  background: var(--accent-soft);
}
.header-right {
  margin-left: auto;
  display: flex;
  gap: 12px;
  align-items: center;
}
.private-badge {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  letter-spacing: 1px;
  color: var(--muted);
  white-space: nowrap;
}
.private-badge > span {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #8e9a88;
}
.mobile-menu {
  display: none;
}
.main-toolbar {
  height: 66px;
  display: grid;
  grid-template-columns: 1fr minmax(140px, 1fr) 1fr;
  align-items: center;
  padding: 0 15px;
  background: var(--surface);
  border-bottom: 1px solid var(--line);
  gap: 16px;
}
.toolbar-leading,
.toolbar-actions {
  display: flex;
  align-items: center;
  gap: 7px;
}
.toolbar-actions {
  justify-content: flex-end;
}
.toolbar-separator {
  width: 1px;
  height: 24px;
  background: var(--line);
  margin: 0 5px;
}
.new-button {
  display: flex;
  gap: 6px;
  align-items: center;
  padding: 6px 9px;
  font-size: 12px;
}
.toolbar-project {
  text-align: center;
  overflow: hidden;
}
.toolbar-project > span {
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  display: block;
  line-height: 1.4;
}
.toolbar-project > small {
  font-size: 12px;
  color: var(--muted);
  letter-spacing: 1.8px;
  display: block;
  margin-top: 3px;
}
.view-switch {
  display: flex;
  border: 1px solid var(--line);
  padding: 2px;
  border-radius: 6px;
  background: var(--bg);
}
.view-switch .icon-button {
  width: 31px;
  height: 25px;
}
.view-switch .is-active {
  background: var(--surface);
  box-shadow: 0 1px 3px #00000015;
}
.compile-button {
  display: flex;
  gap: 7px;
  align-items: center;
  padding: 8px 12px;
  background: var(--accent);
  color: white;
  border-radius: 5px;
  margin-left: 7px;
  font-size: 12px;
}
.dark .compile-button {
  color: #211c22;
}
.dropdown {
  position: absolute;
  top: calc(100% + 5px);
  left: 0;
  min-width: 246px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 7px;
  box-shadow: 0 10px 35px #0002;
  padding: 5px;
  z-index: 60;
  color: var(--text);
}
.dropdown button {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 25px;
  text-align: left;
  width: 100%;
  font-size: 12px;
  padding: 8px 10px;
  white-space: nowrap;
}
.dropdown button:hover {
  background: var(--accent-soft);
  color: var(--accent);
}
kbd {
  font: 12px var(--font-ui);
  color: var(--muted);
  white-space: nowrap;
}
.workspace-layout {
  flex: 1;
  display: flex;
  min-height: 0;
}
.binder {
  width: var(--binder-width);
  min-width: var(--binder-width);
  display: flex;
  flex-direction: column;
  background: var(--side);
}
.resize-gutter {
  width: 3px;
  flex-shrink: 0;
  background: var(--line);
  cursor: col-resize;
  position: relative;
  z-index: 5;
}
.resize-gutter:hover {
  background: #b49ca9;
}
.project-picker {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 20px 17px 17px;
  text-align: left;
  min-height: 79px;
  width: 100%;
}
.project-avatar {
  width: 36px;
  height: 42px;
  background: var(--accent-soft);
  border-radius: 4px 7px 7px 4px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  box-shadow: inset 3px 0 0 #76536a25;
  flex-shrink: 0;
}
.project-picker > span:nth-child(2) {
  flex: 1;
  min-width: 0;
}
.project-picker strong {
  display: block;
  font-size: 12px;
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.project-picker small {
  font-size: 12px;
  display: block;
  color: var(--muted);
  margin-top: 5px;
}
.project-picker > svg {
  color: var(--muted);
}
.binder-search {
  margin: 0 13px 16px;
  display: flex;
  align-items: center;
  gap: 7px;
  border: 1px solid var(--line);
  border-radius: 5px;
  background: var(--surface);
  padding: 7px 8px;
  color: var(--muted);
}
.binder-search input {
  width: 100%;
  min-width: 0;
  border: 0;
  background: none;
  font-size: 12px;
  outline: none;
  padding: 0;
}
.binder-search button {
  padding: 0;
}
.binder-tabs {
  display: flex;
  padding: 0 14px;
  border-bottom: 1px solid var(--line);
  gap: 17px;
  align-items: center;
}
.binder-tabs button {
  font-size: 12px;
  color: var(--muted);
  padding: 6px 0 11px;
  border-radius: 0;
  position: relative;
}
.binder-tabs button.active {
  color: var(--accent);
  font-weight: 600;
}
.binder-tabs button.active:after {
  content: "";
  height: 2px;
  background: var(--accent);
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
}
.binder-tabs > span {
  margin-left: auto;
  font-size: 12px;
  color: var(--muted);
}
.binder-content {
  flex: 1;
  overflow: auto;
  padding-bottom: 20px;
  scrollbar-width: thin;
}
.binder-section-title {
  font-size: 12px;
  letter-spacing: 1.7px;
  font-weight: 600;
  color: var(--muted);
  display: flex;
  justify-content: space-between;
  padding: 23px 20px 11px;
  gap: 10px;
}
.binder-section-title button {
  padding: 0;
}
.binder-section-title > span {
  font-size: 12px;
}
.tree-row {
  display: flex;
  align-items: center;
  height: 33px;
  padding-right: 14px;
  margin: 1px 6px;
  border-radius: 4px;
  gap: 3px;
  position: relative;
}
.tree-row:hover {
  background: #00000004;
}
.tree-row.selected {
  background: var(--accent-soft);
  color: var(--accent);
}
.tree-disclosure {
  width: 13px;
  padding: 0;
  color: var(--muted);
  flex-shrink: 0;
}
.tree-select {
  display: flex;
  align-items: center;
  flex: 1;
  min-width: 0;
  padding: 4px 0;
  gap: 8px;
  text-align: left;
  font-size: 12px;
}
.tree-title {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  flex: 1;
}
.node-icon {
  color: #928a80;
  display: inline-flex;
}
.folder-icon {
  color: #b59f7e;
}
.selected .node-icon {
  color: var(--accent);
}
.tree-select small {
  font-size: 12px;
  color: var(--muted);
}
.label-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
}
.tree-row.dragging {
  opacity: .4;
}
.drop-target {
  box-shadow: inset 0 0 0 1.5px var(--accent);
  background: var(--accent-soft);
}
.binder-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 7px 12px;
  border-top: 1px solid var(--line);
}
.binder-footer > div {
  display: flex;
  gap: 4px;
}
.archive-link {
  display: flex;
  gap: 5px;
  font-size: 12px;
  color: var(--muted);
  padding: 5px;
}
.binder-profile {
  display: flex;
  gap: 9px;
  align-items: center;
  border-top: 1px solid var(--line);
  padding: 13px 17px;
  font-size: 12px;
  line-height: 1.3;
}
.profile-avatar {
  width: 25px;
  height: 25px;
  border: 1px solid #d4c7d0;
  border-radius: 50%;
  background: #e8dfe5;
  color: #785c6e;
  display: flex;
  align-items: center;
  justify-content: center;
  font: italic 14px var(--font-story);
}
.binder-profile > span:nth-child(2) {
  flex: 1;
}
.binder-profile small {
  display: block;
  font-size: 12px;
  letter-spacing: 1.3px;
  color: var(--muted);
  margin-top: 4px;
}
.binder-no-project {
  padding: 50px 20px;
  color: var(--muted);
  text-align: center;
  font-size: 12px;
  line-height: 1.7;
}
.binder-no-project > svg {
  margin-bottom: 8px;
  color: #b6aaa0;
}
.binder-no-project button {
  display: inline-flex;
  gap: 5px;
  align-items: center;
  color: var(--accent);
  margin-top: 4px;
}
.search-result {
  display: flex;
  width: calc(100% - 12px);
  margin: 3px 6px;
  gap: 8px;
  text-align: left;
  padding: 9px 11px;
}
.search-result.selected,
.search-result:hover {
  background: var(--accent-soft);
}
.search-result > svg {
  color: var(--accent);
  margin-top: 1px;
  flex-shrink: 0;
}
.search-result span {
  min-width: 0;
}
.search-result strong {
  font-size: 12px;
  font-weight: 500;
  display: block;
}
.search-result small {
  font-size: 12px;
  line-height: 1.5;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  color: var(--muted);
  margin-top: 4px;
}
.binder-empty {
  padding: 20px;
  color: var(--muted);
  font-size: 12px;
}
.collection-row {
  display: flex;
  align-items: center;
  margin: 2px 16px;
}
.collection-row > button:first-child {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1;
  font-size: 12px;
  text-align: left;
  padding: 6px 0;
}
.collection-row > button:last-child {
  color: var(--muted);
  padding: 3px;
}
.collection-dot {
  width: 7px;
  height: 7px;
  border-radius: 2px;
  background: #ae93a5;
}
.main-editor {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  background: var(--bg);
  position: relative;
}
.document-tabs {
  display: flex;
  align-items: stretch;
  min-height: 35px;
  height: 35px;
  border-bottom: 1px solid var(--line);
  background: var(--side);
  overflow-x: auto;
  overflow-y: visible;
  flex-shrink: 0;
  scrollbar-width: none;
}
.document-tab {
  display: flex;
  align-items: center;
  max-width: 210px;
  min-width: 100px;
  border-right: 1px solid var(--line);
  background: var(--side);
  color: var(--muted);
  flex-shrink: 0;
  padding: 0 6px 0 10px;
  font-size: 12px;
}
.document-tab.active {
  background: var(--surface);
  color: var(--accent);
  position: relative;
}
.document-tab.active:before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 2px;
  background: #a08598;
}
.document-tab > button:first-child {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  padding: 0;
  flex: 1;
}
.document-tab > button:first-child > span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.document-tab svg {
