.index-card.card-drop {
  outline: 2px solid var(--accent);
  outline-offset: 4px;
}
.freeform .card-stage {
  display: block;
  min-width: 850px;
}
.freeform .index-card {
  width: 245px;
  height: 190px;
}
.index-card-head {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 11px 12px;
  border-bottom: 1px solid #e9e1d5;
  color: #a29584;
}
.index-card-head input {
  width: 100%;
  min-width: 0;
  background: none;
  border: 0;
  font-size: 12px;
  font-weight: 600;
  padding: 0;
  color: #635b50;
  outline: none;
}
.dark .index-card-head input {
  color: #d4cbbf;
}
.index-card-head > button {
  padding: 0;
}
.index-card > textarea {
  background:
    repeating-linear-gradient(
      transparent,
      transparent 22px,
      #d9cdbc30 22px,
      #d9cdbc30 23px);
  border: 0;
  border-radius: 0;
  padding: 9px 13px;
  min-height: 100px;
  flex: 1;
  font: 12px/23px var(--font-story);
  resize: vertical;
  color: #7f715f;
  width: 100%;
}
.dark .index-card > textarea {
  color: #c5b8a5;
}
.index-card > textarea::placeholder {
  color: #c1b5a4;
  font-style: italic;
}
.index-card-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 12px;
  color: #ac9f8f;
  padding: 7px 12px;
  border-top: 1px solid #dfd4c540;
}
.trash-actions {
  display: flex;
  gap: 8px;
  padding: 6px 10px;
}
.trash-actions button {
  font-size: 12px;
  color: var(--accent);
}
.empty-board {
  grid-column: 1/-1;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  text-align: center;
  min-height: 320px;
  color: #a79884;
}
.empty-board h2 {
  font: 26px var(--font-story);
  color: #7b6d5a;
  margin: 20px 0 8px;
}
.empty-board p {
  font-size: 12px;
  margin: 0 0 22px;
}
.outliner {
  background: var(--surface);
  min-height: 100%;
  overflow: auto;
}
.outliner table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
  min-width: 580px;
}
.outliner th {
  text-align: left;
  font-weight: 500;
  color: var(--muted);
  font-size: 12px;
  background: var(--bg);
  padding: 11px 15px;
  border-bottom: 1px solid var(--line);
  white-space: nowrap;
}
.outliner td {
  padding: 12px 15px;
  border-bottom: 1px solid var(--line);
  vertical-align: middle;
}
.outliner td:first-child {
  width: 45%;
  min-width: 210px;
}
.outline-title {
  display: flex;
  align-items: center;
  gap: 7px;
  text-align: left;
  font-size: 12px;
  padding: 0;
  font-weight: 500;
}
.outline-title > svg {
  color: var(--accent);
}
.outliner td:first-child > input {
  display: block;
  border: 0;
  background: transparent;
  font: italic 12px/1.5 var(--font-story);
  margin: 6px 0 0 23px;
  padding: 0;
  width: calc(100% - 23px);
  color: var(--muted);
}
.outliner td select {
  font-size: 12px;
  background: var(--bg);
  border: 1px solid var(--line);
  padding: 4px 5px;
  max-width: 105px;
}
.outliner input[type=checkbox] {
  accent-color: var(--accent);
}
.outline-selected {
  background: var(--accent-soft);
}
.row-move {
  display: flex;
}
.row-move .icon-button {
  width: 22px;
  height: 22px;
}
.file-view {
  padding: 28px;
  min-height: 100%;
}
.file-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  margin-bottom: 20px;
}
.file-heading h2 {
  font: 20px var(--font-story);
}
.file-view > iframe {
  width: 100%;
  height: 75vh;
  border: 1px solid var(--line);
  background: white;
}
.file-view > img {
  max-width: 100%;
  display: block;
  margin: auto;
}
.file-view > video {
  max-width: 100%;
}
.file-view > audio {
  width: 100%;
  margin-top: 50px;
}
.empty-small {
  text-align: center;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.7;
  padding: 35px 15px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: center;
}
.empty-small p {
  margin: 0;
}
.save-warning {
  display: flex;
  align-items: center;
  gap: 9px;
  background: #1b1b18;
  color: #e9b66f;
  border-bottom: 1px solid #5a4528;
  padding: 8px 17px;
  font-size: 12px;
  z-index: 21;
}
.save-warning > span {
  flex: 1;
}
.save-warning button {
  font-size: 12px;
  border: 1px solid #6a522e;
  padding: 4px 7px;
  white-space: nowrap;
}
.toast-message {
  position: fixed;
  bottom: 48px;
  left: 50%;
  transform: translateX(-50%);
  background: #413540;
  color: #f6f0f5;
  padding: 12px 18px;
  display: flex;
  gap: 9px;
  align-items: center;
  border-radius: 7px;
  box-shadow: 0 5px 25px #0002;
  z-index: 1000;
  font-size: 12px;
  max-width: 90vw;
  line-height: 1.5;
}
.toast-message > svg {
  color: #b9c3a8;
  flex-shrink: 0;
}
.dialog {
  box-sizing: border-box;
  color: var(--text);
  background: var(--surface);
  width: min(600px, calc(100vw - 35px));
  max-height: calc(100dvh - 70px);
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 12px;
  box-shadow: 0 20px 100px #00000060;
  overflow: auto;
  margin: auto;
  font-size: 12px;
}
.dialog.wide {
  width: min(900px, calc(100vw - 40px));
}
.dialog::backdrop {
  background: #0b100ecc;
  backdrop-filter: blur(3px);
}
.dialog-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  padding: 25px 27px 20px;
  border-bottom: 1px solid var(--line);
  position: sticky;
  top: 0;
  background: var(--surface);
  z-index: 5;
}
.dialog-heading h2 {
  font: 26px/1.2 var(--font-story);
  margin: 0;
  color: var(--text);
  letter-spacing: -.5px;
}
.dialog-heading p {
  font-size: 12px;
  line-height: 1.6;
  margin: 8px 0 0;
  color: var(--muted);
  max-width: 550px;
}
.dialog-heading .icon-button {
  margin: -5px -8px 0 0;
}
.dialog-body {
  padding: 24px 27px;
}
.dialog-body > p {
  font-size: 12px;
  line-height: 1.8;
  color: var(--muted);
}
.form-label {
  display: block;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: .5px;
  color: var(--muted);
  margin: 0 0 20px;
  line-height: 1.5;
}
.form-label input,
.form-label textarea,
.form-label select {
  display: block;
  width: 100%;
  margin-top: 7px;
  padding: 10px 11px;
  border: 1px solid var(--line);
  border-radius: 5px;
  background: var(--bg);
  font-size: 12px;
  color: var(--text);
  letter-spacing: 0;
  font-weight: 400;
}
.form-label input:focus,
.form-label textarea:focus {
  background: var(--surface);
}
.template-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}
.template-card {
  position: relative;
  display: flex;
  flex-direction: column;
  text-align: left;
  padding: 18px 13px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: var(--bg);
  min-height: 160px;
  gap: 10px;
}
.template-card.chosen {
  border-color: var(--accent);
  background: var(--accent-soft);
}
.dark .template-card.chosen {
  background: var(--accent-soft);
}
.template-card > svg:first-child {
  color: #b3a48f;
}
.template-card.chosen > svg:first-child {
  color: var(--accent);
}
.template-card strong {
  font-size: 12px;
  font-weight: 500;
  margin-top: 3px;
}
.template-card span {
  font-size: 12px;
  color: var(--muted);
  line-height: 1.6;
}
.template-card > svg:last-child:not(:first-child) {
  position: absolute;
  right: 10px;
  top: 11px;
  color: var(--accent);
}
.form-note {
  font-size: 12px;
  color: var(--muted);
  line-height: 1.7;
  margin: 18px 0 0;
}
.dialog-actions {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 9px;
  border-top: 1px solid var(--line);
  padding-top: 20px;
  margin-top: 24px;
  flex-wrap: wrap;
}
.dialog-actions.spread {
  justify-content: space-between;
}
.dialog-actions .checkbox-label {
  margin: 0;
}
.project-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.project-list-row {
  display: flex;
  align-items: center;
  gap: 10px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--bg);
  padding: 11px 14px;
}
.project-list-row > button:first-child {
  display: flex;
  align-items: center;
  gap: 13px;
  text-align: left;
  flex: 1;
  padding: 0;
}
.project-list-row > button:first-child > span:nth-child(2) {
  flex: 1;
  min-width: 0;
}
.project-list-row strong {
  font-size: 13px;
  font-weight: 500;
  display: block;
}
.project-list-row small {
  font-size: 12px;
  color: var(--muted);
  display: block;
  margin-top: 6px;
}
.settings-columns {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px;
}
.settings-columns h3,
.help-grid h3 {
  font-size: 12px;
  font-weight: 600;
  margin: 0 0 20px;
}
.settings-columns .checkbox-label {
  margin: 18px 0;
  font-size: 12px;
}
.settings-archive {
  display: flex;
  align-items: center;
  gap: 13px;
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 15px;
  margin-top: 20px;
  color: var(--muted);
}
.settings-archive > div {
  flex: 1;
}
.settings-archive strong {
  font-size: 12px;
  font-weight: 500;
  color: var(--text);
}
.settings-archive p {
  font-size: 12px;
  line-height: 1.6;
  margin: 5px 0 0;
}
.settings-archive .button {
  font-size: 12px;
  padding: 7px 9px;
}
.scratchpad {
  width: 100%;
  min-height: 350px;
  background: #fcf8ef;
  border: 1px solid #e4ddce;
  font: 16px/1.9 var(--font-story);
  padding: 20px;
  color: #766651;
  resize: vertical;
}
.dark .scratchpad {
  background: #3a342c;
  color: #d4c6b2;
  border-color: #554936;
}
.target-summary {
  text-align: center;
  padding: 8px 0 25px;
}
.target-summary > strong {
  display: block;
  font: 48px var(--font-story);
  color: var(--accent);
  margin: 13px 0;
}
.target-summary > span {
  font-size: 12px;
  color: var(--muted);
}
.target-meter {
  height: 5px;
  background: var(--line);
  border-radius: 4px;
  margin: 15px auto 10px;
  max-width: 300px;
  overflow: hidden;
}
.target-meter > i {
  display: block;
  height: 100%;
  background: var(--accent);
}
.history-totals {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 15px;
  margin-bottom: 30px;
}
.history-totals > div {
  text-align: center;
  border-right: 1px solid var(--line);
}
.history-totals > div:last-child {
  border: 0;
}
.history-totals strong {
  display: block;
  font: 30px var(--font-story);
  color: var(--accent);
}
.history-totals span {
  display: block;
  font-size: 12px;
  color: var(--muted);
  margin-top: 8px;
}
.history-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}
.history-table th {
  text-align: left;
  font-size: 12px;
  font-weight: 500;
  color: var(--muted);
}
.history-table td,
.history-table th {
  padding: 10px;
  border-bottom: 1px solid var(--line);
}
.history-table td:last-child {
  width: 40%;
}
.history-bar {
  height: 5px;
  background: var(--bg);
}
.history-bar i {
  height: 100%;
  display: block;
  background: var(--accent);
  border-radius: 4px;
}
.compile-layout {
  display: grid;
  grid-template-columns: 1fr 1.1fr;
  gap: 30px;
}
.compile-manifest {
  background: var(--bg);
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 6px;
  max-height: 340px;
  overflow: auto;
}
.compile-item {
  display: flex;
  gap: 8px;
  align-items: center;
  font-size: 12px;
  padding: 10px 0;
  border-bottom: 1px solid var(--line);
}
.compile-item > span {
  font-size: 12px;
  color: var(--muted);
}
.compile-item strong {
  flex: 1;
  font-weight: 400;
}
.compile-item small {
  font-size: 12px;
  color: var(--muted);
}
.compile-item svg {
  color: var(--accent);
}
.compile-total {
  text-align: right;
  font-size: 12px;
  color: var(--muted);
  padding-top: 15px;
}
.compile-preview {
  height: 430px;
  width: 100%;
  margin-top: 20px;
  border: 1px solid var(--line);
  background: white;
}
.compare-columns {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 22px;
}
.compare-columns > section {
  min-width: 0;
}
.compare-columns .section-label {
  margin-bottom: 8px;
}
.compare-columns small {
  font-size: 12px;
  color: var(--muted);
}
.compare-text {
  font: 13px/1.8 var(--font-story);
  padding: 18px;
  background: var(--bg);
  border: 1px solid var(--line);
  min-height: 200px;
  max-height: 480px;
  overflow: auto;
  margin-top: 13px;
  overflow-wrap: anywhere;
}
.compare-text p {
  margin: 0 0 1em;
}
.vault-search {
  display: flex;
  align-items: center;
  gap: 9px;
  border: 1px solid var(--line);
  background: var(--bg);
  padding: 10px 12px;
  border-radius: 5px;
  margin-bottom: 20px;
  color: var(--muted);
}
.vault-search input {
  border: 0;
  background: none;
  font-size: 12px;
  width: 100%;
  outline: none;
}
.vault-entries {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 55vh;
  overflow: auto;
}
.vault-entry {
  border: 1px solid var(--line);
  border-radius: 6px;
}
.vault-entry summary {
  display: flex;
  gap: 13px;
  align-items: center;
  cursor: pointer;
  list-style: none;
  padding: 13px;
  font-size: 12px;
}
.vault-entry summary::-webkit-details-marker {
  display: none;
}
.vault-entry summary strong {
  font-weight: 500;
  flex: 1;
}
.vault-entry summary > span:nth-last-child(2) {
  color: var(--muted);
  font-size: 12px;
}
.vault-entry-kind {
  font-size: 12px;
  color: var(--accent);
  background: var(--accent-soft);
  padding: 4px 6px;
  border-radius: 3px;
  min-width: 62px;
  text-align: center;
}
.vault-entry-content {
  padding: 16px;
  border-top: 1px solid var(--line);
}
.vault-entry-content pre {
  font: 12px/1.8 var(--font-ui);
  white-space: pre-wrap;
  margin: 0 0 20px;
  overflow-wrap: anywhere;
}
.attachment-links {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 20px;
}
.attachment-links a {
  display: flex;
  gap: 6px;
  align-items: center;
  font-size: 12px;
  color: var(--accent);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 8px;
}
.help-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 35px;
}
.help-grid h3 {
  display: flex;
  gap: 8px;
  align-items: center;
  margin: 0 0 10px;
}
.help-grid h3 svg {
  color: var(--accent);
}
.help-grid p {
  font-size: 12px;
  line-height: 1.9;
  color: var(--muted);
  margin: 0 0 25px;
}
.shortcut-list {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px;
  font-size: 12px;
  color: var(--muted);
}
.help-note {
  font-size: 12px;
  line-height: 1.7;
  padding: 15px;
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 5px;
  color: var(--muted);
  margin-top: 20px;
}
.composition .app-header,
.composition .document-tabs,
.composition .document-heading,
.composition .formatbar {
  display: none;
}
.composition .editor-body {
  padding: 0 10vw;
  background: #383038;
}
.composition .editor-document {
  padding-top: 45px;
}
.composition .paper {
  max-width: 850px;
  min-height: calc(100vh - 80px);
}
.composition .main-editor {
  background: #383038;
}
.exit-composition {
  position: fixed;
  right: 18px;
  top: 16px;
  z-index: 30;
  opacity: .6;
}
.exit-composition:hover {
  opacity: 1;
}
.exit-composition kbd {
  margin-left: 5px;
}
.composition .script-strip {
  color: #c6b8c1;
}
.composition .editor-footer {
  background: #302a31;
  border-color: #534555;
  color: #b0a2ad;
}
.composition .save-status.saved {
  color: #a6b198;
}
@media (min-width: 1600px) {
  .paper {
    min-height: 1056px;
  }
  .welcome h1 {
    font-size: 62px;
  }
  .welcome > p {
    font-size: 13px;
  }
  .welcome-symbol {
    margin-bottom: 35px;
  }
}
@media (max-width: 1200px) {
  .main-toolbar {
    grid-template-columns: 1fr 1fr;
    gap: 10px;
  }
  .toolbar-project {
    display: none;
  }
  .toolbar-actions {
    gap: 4px;
  }
  .inspector {
    width: 244px;
    min-width: 244px;
  }
  .binder {
    width: 220px;
    min-width: 220px;
  }
  .inspector-tabs {
    gap: 7px;
  }
  .inspector-tabs .icon-button {
    width: 30px;
  }
  .editor-document {
    padding: 25px 25px 45px;
  }
  .paper {
    padding: 50px 45px;
  }
  .screenplay {
    padding: 50px 38px 50px 55px;
  }
  .menubar {
    gap: 15px;
  }
  .menubar nav .menu-host > button {
    padding-left: 6px;
    padding-right: 6px;
  }
  .private-badge {
    font-size: 12px;
  }
  .document-heading {
    padding-left: 20px;
    padding-right: 20px;
  }
  .formatbar {
    padding-left: 8px;
  }
  .script-hint {
    display: none;
  }
  .welcome-bottom {
    gap: 15px;
  }
  .format-tools .icon-button:nth-last-child(-n+3) {
    display: none;
  }
}
@media (max-width: 950px) {
  .inspector {
    position: absolute;
    right: 0;
    top: 103px;
    bottom: 0;
    z-index: 15;
    box-shadow: -8px 0 30px #0001;
    width: 270px;
    min-width: 270px;
    border-left: 1px solid var(--line);
  }
  .resize-gutter:has(+ .inspector) {
    display: none;
  }
  .inspector-tabs {
    gap: 10px;
  }
  .inspector-tabs .icon-button {
    width: 34px;
  }
  .header-right .private-badge {
    display: none;
  }
  .main-toolbar .toolbar-actions > .toolbar-separator {
    margin: 0 2px;
  }
  .menubar nav .menu-host > button {
    font-size: 12px;
  }
  .binder {
    width: 218px;
    min-width: 218px;
  }
  .toolbar-project {
    display: none;
  }
  .welcome h1 {
    font-size: 45px;
  }
  .dialog-heading {
    padding-left: 22px;
  }
  .dialog-body {
    padding: 22px;
  }
  .index-card {
    min-height: 185px;
  }
  .card-stage {
    gap: 16px;
    padding: 20px;
    grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));
  }
}
@media (max-width: 700px) {
  .menubar {
    height: 40px;
    padding: 0 12px;
    gap: 10px;
  }
  .menubar nav {
    display: none;
  }
  .mobile-menu {
    display: block;
    margin-left: 6px;
    color: var(--muted);
  }
