.studio.atlas-shell,
.studio.atlas-shell.dark[data-palette=carbon] {
  --bg: #171717;
  --side: #202020;
  --surface: #292929;
  --line: #3b3b3b;
  --text: #e6e5e1;
  --secondary: #bdbcb8;
  --muted: #9e9e9a;
  --accent: #d2d0c9;
  --accent-soft: #353534;
  --on-accent: #171717;
  --paper: #242424;
  --editor: #171717;
  --control-border: #777773;
  --approved: #9fbaa7;
  --progress: #b5babd;
  --blocked: #d69b95;
  --draft: #a7a7a3;
  --tungsten: #bdbcb8;
  --warning: #cfb58b;
