  background: transparent;
  border-radius: 5px;
}
.atlas-shell .save-warning button:hover {
  background: var(--surface);
}
.atlas-shell .toast-message > svg {
  color: var(--approved);
}
.atlas-shell .welcome-symbol:after {
  display: none;
}
.atlas-shell .compile-button:not(:disabled):hover,
.atlas-shell .button.primary:not(:disabled):hover {
  background: #e6e5e1;
  border-color: #e6e5e1;
}
.atlas-shell .file-view > iframe {
